<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><form class="modal" @submit.prevent="$emit('save',{...form})"><div class="modal-head"><div><h2>{{project?'Editar projeto':'Novo projeto'}}</h2><p>Crie uma iniciativa para sua equipe.</p></div><button type="button" @click="$emit('close')"><X/></button></div><label>Nome<input v-model="form.name" required/></label><label class="description-label">Descrição<textarea v-model="form.description" required/></label><div class="modal-fields"><label>Data de início<input v-model="form.start" type="date"/></label><label>Prazo<input v-model="form.due" type="date"/></label></div><fieldset class="member-picker"><legend>Membros participantes</legend><label v-for="m in members"><input v-model="form.members" type="checkbox" :value="m.id"/>{{m.name}}</label></fieldset><div class="modal-actions"><span/><button type="button" class="cancel" @click="$emit('close')">Cancelar</button><button v-if="project" type="button" class="delete-btn" @click="$emit('remove',project.id)">Excluir</button><button class="primary-btn"><Plus/>{{project?'Salvar projeto':'Criar projeto'}}</button></div></form></div></template>
<script setup lang="ts">import{reactive}from"vue";import{Plus,X}from"lucide-vue-next";import type{Member,Project}from"../stores/taskflow";const props=defineProps<{members:Member[];project?:Project}>();defineEmits(["close","save","remove"]);const form=reactive<Project>(props.project?{...props.project,members:[...props.project.members]}:{id:Date.now(),name:"",description:"",start:new Date().toISOString().slice(0,10),due:"2026-10-30",members:props.members.slice(0,1).map(m=>m.id),color:"#6c5ce7"});</script>
